initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Create Context Source Registration with Response Status Code set to 400     and
        Create Context Source Registration with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData'     and
        Create Context Source Registration with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations'
        method set to 'POST'
        Create Context Source Registration Request with Content-Type set to 'application/ld+json' and payload set to '${subscription_payload}'
}
